import type { PersonaKey } from "./characterSheet";

/**
 * What each Kindred's own tables offer the identity fields.
 *
 * **GENERATED by extract-lore.mjs — do not edit by hand.** Six Kindreds, each
 * with the d20 background table and the eight d12 persona tables the Player's
 * Book prints for it (p33-53).
 *
 * **The tables are per Kindred, which is why the sheet's suggestions follow the
 * Kindred field.** A breggle's backgrounds are onion farmers and standard-
 * bearers; an elf's are poets and unicorn handlers. One merged list would offer
 * every character everything and would be nobody's table.
 *
 * **The third one is called Fur on two of these sheets.** Breggles and
 * grimalkins have fur where the others have a body, so the field keeps its key
 * and borrows the Kindred's word for its label — the alternative was a seventh
 * persona field that four Kindreds would leave empty.
 *
 * Nothing here is imposed: these fill datalists, and the fields stay typeable.
 * A character who is none of the six simply gets no suggestions.
 */
export interface KindredTables {
  /** What this Kindred's book calls the third persona field: "Body" or "Fur". */
  bodyLabel: string;
  /** The d20 background table, in the book's order. */
  backgrounds: string[];
  /** The eight d12 tables, keyed as the sheet keys its persona fields. */
  persona: Record<Exclude<PersonaKey, "birthday" | "height" | "weight">, string[]>;
}

